-- A dentist who does work on a patient (dentist on a bill line, or the procedure's dentist) is assigned to that patient,
-- like booking with a dentist does, so the case shows in their My cases. Past work is caught up once.
INSERT OR IGNORE INTO patient_assignments (patient_id, dentist_id, created_at) SELECT DISTINCT i.patient_id, ii.dentist_id, datetime('now', 'localtime') FROM invoice_items ii JOIN invoices i ON i.id = ii.invoice_id JOIN users u ON u.id = ii.dentist_id WHERE ii.dentist_id IS NOT NULL AND i.status != 'void' AND u.role = 'dentist';
INSERT OR IGNORE INTO patient_assignments (patient_id, dentist_id, created_at) SELECT DISTINCT p.patient_id, p.performed_by, datetime('now', 'localtime') FROM procedures p JOIN users u ON u.id = p.performed_by WHERE p.performed_by IS NOT NULL AND u.role = 'dentist';
CREATE TRIGGER trg_assign_line_dentist_ins AFTER INSERT ON invoice_items WHEN NEW.dentist_id IS NOT NULL BEGIN INSERT OR IGNORE INTO patient_assignments (patient_id, dentist_id, created_at) SELECT i.patient_id, NEW.dentist_id, datetime('now', 'localtime') FROM invoices i JOIN users u ON u.id = NEW.dentist_id AND u.role = 'dentist' WHERE i.id = NEW.invoice_id; END;
CREATE TRIGGER trg_assign_line_dentist_upd AFTER UPDATE OF dentist_id ON invoice_items WHEN NEW.dentist_id IS NOT NULL BEGIN INSERT OR IGNORE INTO patient_assignments (patient_id, dentist_id, created_at) SELECT i.patient_id, NEW.dentist_id, datetime('now', 'localtime') FROM invoices i JOIN users u ON u.id = NEW.dentist_id AND u.role = 'dentist' WHERE i.id = NEW.invoice_id; END;
CREATE TRIGGER trg_assign_proc_dentist_ins AFTER INSERT ON procedures WHEN NEW.performed_by IS NOT NULL BEGIN INSERT OR IGNORE INTO patient_assignments (patient_id, dentist_id, created_at) SELECT NEW.patient_id, u.id, datetime('now', 'localtime') FROM users u WHERE u.id = NEW.performed_by AND u.role = 'dentist'; END;
CREATE TRIGGER trg_assign_proc_dentist_upd AFTER UPDATE OF performed_by ON procedures WHEN NEW.performed_by IS NOT NULL BEGIN INSERT OR IGNORE INTO patient_assignments (patient_id, dentist_id, created_at) SELECT NEW.patient_id, u.id, datetime('now', 'localtime') FROM users u WHERE u.id = NEW.performed_by AND u.role = 'dentist'; END
